def determinant(matrix):
    if len(matrix) == 1:
        return matrix[0][0]
    total = 0
    for j, value in enumerate(matrix[0]):
        minor = [row[:j] + row[j + 1 :] for row in matrix[1:]]
        term = value * determinant(minor)
        total += term if j % 2 == 0 else -term
    return total
